def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    import heapq

    times = sorted({time for start, end, _ in jobs for time in (start, end)})
    index = {time: i for i, time in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, len(graph[v]), capacity, cost])
        graph[v].append([u, len(graph[u]) - 1, 0, -cost])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest-path distances are easy to find in the forward DAG.
    inf = float("inf")
    potential = [inf] * n
    potential[0] = 0
    for u in range(n):
        for v, _, capacity, cost in graph[u]:
            if capacity and potential[u] + cost < potential[v]:
                potential[v] = potential[u] + cost

    total_cost = 0
    flow = 0

    while flow < k:
        dist = [inf] * n
        dist[0] = 0
        parent = [None] * n
        heap = [(0, 0)]

        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            for edge_index, (v, _, capacity, cost) in enumerate(graph[u]):
                if not capacity:
                    continue
                new_dist = d + cost + potential[u] - potential[v]
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    parent[v] = (u, edge_index)
                    heapq.heappush(heap, (new_dist, v))

        if dist[-1] == inf:
            break

        for v in range(n):
            if dist[v] != inf:
                potential[v] += dist[v]

        amount = k - flow
        v = n - 1
        while v != 0:
            u, edge_index = parent[v]
            amount = min(amount, graph[u][edge_index][2])
            v = u

        v = n - 1
        while v != 0:
            u, edge_index = parent[v]
            edge = graph[u][edge_index]
            total_cost += amount * edge[3]
            edge[2] -= amount
            graph[v][edge[1]][2] += amount
            v = u

        flow += amount

    return -total_cost
